t.script:
            (function () {
                var approveBtn = document.getElementById('ap_approve');
                if (!approveBtn) { return; }
                var rejectBtn = document.getElementById('ap_reject');
                var statusEl = document.getElementById('ap_status');
                var requestId = parseInt(approveBtn.dataset.requestId, 10);

                function b64urlToBuf(value) {
                    var padded = value.replace(/-/g, '+').replace(/_/g, '/');
                    while (padded.length % 4) { padded += '='; }
                    var raw = atob(padded);
                    var buf = new Uint8Array(raw.length);
                    for (var i = 0; i < raw.length; i++) { buf[i] = raw.charCodeAt(i); }
                    return buf.buffer;
                }
                function bufToB64url(buf) {
                    var bytes = new Uint8Array(buf), str = '';
                    for (var i = 0; i < bytes.length; i++) { str += String.fromCharCode(bytes[i]); }
                    return btoa(str).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
                }
                function rpc(url, params) {
                    return fetch(url, {
                        method: 'POST',
                        headers: {'Content-Type': 'application/json'},
                        body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: params || {}})
                    }).then(function (r) { return r.json(); }).then(function (payload) {
                        if (payload.error) {
                            throw new Error(payload.error.data ? payload.error.data.message
                                                               : payload.error.message);
                        }
                        return payload.result;
                    });
                }
                function say(message, ok) {
                    statusEl.innerHTML = '
' + message + '';
                }

                approveBtn.addEventListener('click', function () {
                    approveBtn.disabled = true;
                    say('Waiting for your device…', true);
                    rpc('/override/approve/options', {request_id: requestId})
                    .then(function (options) {
                        if (options.error) { throw new Error(options.error); }
                        options.challenge = b64urlToBuf(options.challenge);
                        (options.allowCredentials || []).forEach(function (c) {
                            c.id = b64urlToBuf(c.id);
                        });
                        return navigator.credentials.get({publicKey: options});
                    })
                    .then(function (assertion) {
                        return rpc('/override/approve/submit', {
                            request_id: requestId,
                            credential: {
                                id: assertion.id,
                                rawId: bufToB64url(assertion.rawId),
                                type: assertion.type,
                                response: {
                                    clientDataJSON: bufToB64url(assertion.response.clientDataJSON),
                                    authenticatorData: bufToB64url(assertion.response.authenticatorData),
                                    signature: bufToB64url(assertion.response.signature),
                                    userHandle: assertion.response.userHandle
                                        ? bufToB64url(assertion.response.userHandle) : null
                                }
                            }
                        });
                    })
                    .then(function (result) {
                        if (result.ok) {
                            say(result.fully_approved
                                ? 'Approved. This was the final approval; the override is now executable.'
                                : 'Approved. The request moves to the next tier.', true);
                        } else {
                            say(result.error, false);
                            approveBtn.disabled = false;
                        }
                    })
                    .catch(function (err) {
                        say('Approval failed: ' + err.message, false);
                        approveBtn.disabled = false;
                    });
                });

                rejectBtn.addEventListener('click', function () {
                    rejectBtn.disabled = true;
                    rpc('/override/reject/submit', {
                        request_id: requestId,
                        comment: document.getElementById('ap_comment').value
                    }).then(function (result) {
                        if (result.ok) {
                            say('Rejected. The requester has been notified.', true);
                        } else {
                            say(result.error, false);
                            rejectBtn.disabled = false;
                        }
                    }).catch(function (err) {
                        say('Rejection failed: ' + err.message, false);
                        rejectBtn.disabled = false;
                    });
                });
            })();
